('MPM2D', 'analytic-geometry', 'midpoint-and-length-of-a-line-segment', 13, 'Easy',
 'What is the midpoint of the segment from (-1, 2) to (3, -4)?', 3,
 '[
   {"text": "(1, 1)", "feedback": "Watch the signs in the y average: 2 + (-4) is negative, so halving it cannot leave a positive number."},
   {"text": "(2, -2)", "feedback": "The x coordinates average to 1, not 2: -1 + 3 is 2, halved."},
   {"text": "(2, -3)", "feedback": "That is half the DIFFERENCE of the endpoints. A midpoint averages them: add, then halve."},
   {"text": "(1, -1)", "feedback": "Correct."}
 ]'::jsonb,
