('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 19, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(5, 0), C(8, 4), and D(3, 4). Using slopes, what shape is ABCD?', 0,
 '[{"text": "Parallelogram (not a rectangle)", "feedback": "Correct. Slope of AB = slope of DC = 0, and slope of AD = slope of BC = 4/3 — both pairs of opposite sides are parallel, but 0 and 4/3 don''t multiply to −1, so it isn''t a rectangle."}, {"text": "Rectangle", "feedback": "Check whether adjacent sides are perpendicular — the slopes 0 and 4/3 don''t multiply to −1, so there are no right angles here."}, {"text": "Trapezoid", "feedback": "A trapezoid has only one pair of parallel sides — check the slope of AD and BC as well as AB and DC."}, {"text": "Not a special quadrilateral", "feedback": "Both pairs of opposite sides actually do turn out parallel here, which is more than a general quadrilateral guarantees."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 20, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(6, 0), C(4, 3), and D(1, 3). Using slopes, what shape is ABCD?', 3,
 '[{"text": "Parallelogram", "feedback": "Check the slope of AD against BC — they come out different, so only one pair of opposite sides is actually parallel."}, {"text": "Rectangle", "feedback": "A rectangle needs both pairs of sides parallel and adjacent sides perpendicular — here, only one pair of sides is even parallel."}, {"text": "Kite", "feedback": "A kite has two pairs of adjacent sides equal, with no sides parallel — but here, AB and DC actually are parallel."}, {"text": "Trapezoid", "feedback": "Correct. Slope of AB = slope of DC = 0, so that pair is parallel, but slope of AD (3) and BC (−1.5) are different — with only one pair of parallel sides, this is a trapezoid."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 21, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(3, 1), C(5, 5), and D(1, 3). Is ABCD a parallelogram?', 1,
 '[{"text": "Yes, since AB is parallel to DC", "feedback": "Recompute both slopes: AB has slope 1/3 and DC has slope 1/2 — these are different, so this pair of sides is not parallel."}, {"text": "No, neither pair of opposite sides is parallel", "feedback": "Correct. Slope of AB (1/3) ≠ slope of DC (1/2), and slope of AD (3) ≠ slope of BC (2) — with neither pair of opposite sides parallel, this isn''t a parallelogram."}, {"text": "Yes, since AD is parallel to BC", "feedback": "Recompute both slopes: AD has slope 3 and BC has slope 2 — these are different, so this pair of sides is not parallel either."}, {"text": "Yes, all four sides are parallel to each other", "feedback": "No two sides here share a slope — recompute all four slopes and compare them in opposite pairs."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 22, 'Medium',
 'Triangle with vertices (0, 0), (4, 0) and (2, 6) is best described as what?', 0,
 '[
   {"text": "Isosceles, because two sides have equal length", "feedback": "Correct."},
   {"text": "Scalene, because the vertices are all different", "feedback": "Different vertices are guaranteed in any triangle. Compare the side LENGTHS."},
   {"text": "Right angled at (2, 6)", "feedback": "Check the slopes from (2, 6): 3 and -3 multiply to -9, not -1."},
   {"text": "Equilateral, because it looks even", "feedback": "Looks are not a proof. The base is 4 but the other two sides are √40 — only TWO match."}
 ]'::jsonb,
 null),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 23, 'Medium',
 'M and N are midpoints of two sides of a triangle. The segment MN compares to the third side how?', 1,
 '[
   {"text": "Perpendicular to it", "feedback": "A midsegment runs alongside the third side, never across it."},
   {"text": "Parallel to it and half its length", "feedback": "Correct."},
   {"text": "Parallel to it and equal in length", "feedback": "Equal length would make a parallelogram of the whole triangle. The midsegment is HALF."},
   {"text": "Half its length but at a different slope", "feedback": "Same slope is the whole point — the midpoints preserve direction."}
 ]'::jsonb,
 null),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 24, 'Medium',
 'To verify the diagonals of a parallelogram bisect each other, what should be compared?', 3,
 '[
   {"text": "The midpoints of the two opposite sides", "feedback": "The claim is about the diagonals, so their midpoints are what must coincide."},
   {"text": "The slopes of each of the two diagonals", "feedback": "Slopes test parallel or perpendicular, not cutting in half."},
   {"text": "The lengths of each of the two diagonals", "feedback": "Diagonals of a parallelogram are usually DIFFERENT lengths. Bisecting is about midpoints."},
   {"text": "The midpoints of the two diagonals", "feedback": "Correct."}
 ]'::jsonb,
 null),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 25, 'Challenge',
 'What is the slope of the line through (3, −2) and (3, 7)?', 2,
 '[{"text": "0", "feedback": "A slope of 0 belongs to a horizontal line, where the y-coordinates match. Here it''s the x-coordinates that match."}, {"text": "9", "feedback": "This is the difference in y-values alone. Slope needs that change compared to the change in x."}, {"text": "Undefined", "feedback": "Correct. Both points share x = 3, so the run is 0 — dividing by a run of 0 makes the slope undefined, and the line is vertical."}, {"text": "1", "feedback": "Recompute rise over run: with both x-coordinates equal to 3, the run is 0, not 1."}]'::jsonb,
 'vertical-line-slope'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 26, 'Challenge',
 'Triangle ABC has A(1, 1), B(4, 5), and C(8, 2). Using the distance formula on all three sides, classify the triangle.', 3,
 '[{"text": "Scalene", "feedback": "Two of the three side lengths actually come out equal — recompute AB and BC and compare them."}, {"text": "Equilateral", "feedback": "AC works out longer than the other two sides, so all three lengths aren''t equal."}, {"text": "Isosceles only (not right)", "feedback": "The triangle is isosceles, but check whether AB² + BC² equals AC² before ruling out a right angle."}, {"text": "Isosceles right triangle", "feedback": "Correct. AB = √(3²+4²) = 5, BC = √(4²+3²) = 5 (isosceles), and AB² + BC² = 50 = AC², so angle B is a right angle."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 27, 'Challenge',
 'A line is parallel to y = ⅔x − 1 and passes through (6, 5). What is its equation?', 2,
 '[{"text": "y = ⅔x − 1", "feedback": "This is the original line itself — a parallel line has the same slope but must be shifted to pass through the new point."}, {"text": "y = −³⁄₂x + 14", "feedback": "This uses the negative reciprocal slope, which belongs to a perpendicular line, not a parallel one."}, {"text": "y = ⅔x + 1", "feedback": "Correct. A parallel line keeps the same slope, ⅔; substituting (6, 5) into y = ⅔x + b gives 5 = 4 + b, so b = 1."}, {"text": "y = ⅔x + 5", "feedback": "This uses the point''s y-coordinate directly as the intercept, without solving 5 = ⅔(6) + b for b."}]'::jsonb,
 'parallel-line-through-point'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 28, 'Challenge',
 'A line is perpendicular to y = −4x + 2 and passes through (8, −3). What is its equation?', 1,
 '[{"text": "y = −4x + 29", "feedback": "This keeps the original slope, which gives a parallel line — a perpendicular line needs the negative reciprocal slope instead."}, {"text": "y = ¼x − 5", "feedback": "Correct. The negative reciprocal of −4 is ¼; substituting (8, −3) into y = ¼x + b gives −3 = 2 + b, so b = −5."}, {"text": "y = −¼x + 1", "feedback": "This flips the sign but not the fraction — the negative reciprocal of −4 is ¼, not −¼."}, {"text": "y = ¼x − 3", "feedback": "This uses the point''s y-coordinate directly as the intercept, without solving −3 = ¼(8) + b for b."}]'::jsonb,
 'perpendicular-line-through-point'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 29, 'Challenge',
 'What is the slope of a line perpendicular to 3x + 4y = 12?', 3,
 '[{"text": "3/4", "feedback": "This reuses the coefficient of x directly rather than first rewriting the equation in y = mx + b form."}, {"text": "−3/4", "feedback": "This is the original line''s own slope — a perpendicular line needs the negative reciprocal of it instead."}, {"text": "−4/3", "feedback": "This is the negative of the original slope, not its reciprocal — both the flip and the sign change are needed."}, {"text": "4/3", "feedback": "Correct. Rewriting 3x + 4y = 12 gives y = −¾x + 3, so the original slope is −¾, and its negative reciprocal is 4/3."}]'::jsonb,
 'perpendicular-slope-from-standard-form'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 30, 'Challenge',
 'A line passes through (0, 0) and (4, 6). Is this line parallel, perpendicular, or neither to the line y = −⅔x + 5?', 1,
 '[{"text": "Parallel", "feedback": "Parallel would require the same slope — this line''s slope is 3/2, while the given line''s is −2/3."}, {"text": "Perpendicular", "feedback": "Correct. The slope through (0,0) and (4,6) is 6/4 = 3/2, and (3/2) × (−2/3) = −1, so the two lines are perpendicular."}, {"text": "Neither", "feedback": "Check the product of the two slopes, 3/2 and −2/3 — it comes out to exactly −1, which is the perpendicularity test."}, {"text": "The same line", "feedback": "The two lines have different slopes (3/2 versus −2/3), so they can''t be the same line."}]'::jsonb,
 'parallel-perpendicular-or-neither'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 31, 'Challenge',
 'Triangle ABC has A(1, 2), B(4, 6), and C(9, 4). Using the distance formula on all three sides, classify the triangle.', 2,
 '[{"text": "Isosceles", "feedback": "Recompute all three squared side lengths: AB²=25, BC²=29, AC²=68 — none of these match, so no two sides are equal."}, {"text": "Right", "feedback": "Check whether any two of the squared side lengths (25, 29, 68) add up to the third — none of the three combinations work out."}, {"text": "Scalene", "feedback": "Correct. AB² = 3²+4² = 25, BC² = 5²+2² = 29, and AC² = 8²+2² = 68 — all three are different, so no two sides are equal, making this triangle scalene."}, {"text": "Equilateral", "feedback": "All three squared side lengths (25, 29, 68) are different — equilateral needs all three sides to be exactly equal."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 32, 'Challenge',
 'Triangle ABC has A(0, 0), B(4, 3), and C(8, 0). Using the distance formula on all three sides, classify the triangle.', 1,
 '[{"text": "Scalene", "feedback": "Recompute all three squared side lengths: AB²=25, BC²=25, AC²=64 — two of these actually match."}, {"text": "Isosceles (but not right)", "feedback": "Correct. AB² = 4²+3² = 25 and BC² = 4²+3² = 25 are equal (isosceles), but AB² + AC² = 25 + 64 = 89 ≠ BC² = 25 and no other combination matches either, so there''s no right angle."}, {"text": "Right (but not isosceles)", "feedback": "Two of the three squared side lengths (AB²=25 and BC²=25) actually are equal, which does make this triangle isosceles — but check whether any two lengths add to the third; none do, so there''s no right angle."}, {"text": "Equilateral", "feedback": "AC² = 64, which doesn''t match AB² or BC² (both 25) — equilateral needs all three sides equal."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 33, 'Challenge',
 'Triangle ABC has A(0, 0), B(5, 0), and C(0, 12). Using the distance formula on all three sides, classify the triangle.', 3,
 '[{"text": "Isosceles right triangle", "feedback": "Check the three squared side lengths (25, 169, 144) carefully — none of them match each other, so this triangle isn''t isosceles."}, {"text": "Equilateral", "feedback": "The three squared side lengths (25, 169, 144) are all different — equilateral needs all three sides exactly equal."}, {"text": "Scalene, with no right angle", "feedback": "Check whether any two of the squared side lengths add up to the third: 25 + 144 = 169 — that condition is actually satisfied."}, {"text": "Scalene right triangle", "feedback": "Correct. AB²=25, AC²=144, BC²=169, and all three are different (scalene); since AB² + AC² = 25+144 = 169 = BC², there''s also a right angle at A."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 34, 'Challenge',
 'Triangle ABC has A(2, 1), B(2, 7), and C(8, 1). Using the distance formula on all three sides, classify the triangle.', 0,
 '[{"text": "Isosceles right triangle", "feedback": "Correct. AB²=36 and AC²=36 are equal (isosceles), and AB² + AC² = 36+36 = 72 = BC², so there''s also a right angle at A."}, {"text": "Scalene right triangle", "feedback": "Two of the three squared side lengths (AB²=36 and AC²=36) actually come out equal — recheck whether all three sides are really different."}, {"text": "Isosceles, but not right", "feedback": "Check whether any two of the squared side lengths add up to the third: 36 + 36 = 72, which matches BC² exactly."}, {"text": "Equilateral", "feedback": "BC² = 72, which doesn''t match AB² or AC² (both 36) — equilateral needs all three sides exactly equal."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 35, 'Challenge',
 'Triangle has A(-1, 2), B(3, 4), C(5, 0). Where is its right angle?', 2,
 '[
   {"text": "It has no right angle", "feedback": "One pair of sides here does meet at a right angle. Test the slopes at each vertex before ruling it out."},
