   {"text": "Isosceles but not right angled", "feedback": "32 + 32 equals 64, which is AC². Pythagoras confirms a right angle at B too."}
 ]'::jsonb,
 null),
('MPM2D', 'analytic-geometry', 'geometric-properties-of-shapes', 49, 'Advanced',
